/* ============================================================
   Entire — web deck
   Brand tokens extracted from entire.io production CSS
   ============================================================ */

@font-face {
  font-family: "Entire Headline";
  src: url("../fonts/entire-headline-semibold.woff2") format("woff2");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Entire Headline";
  src: url("../fonts/entire-headline-semibolditalic.woff2") format("woff2");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}
@font-face {
  font-family: "Entire Mono";
  src: url("../fonts/entire-mono-regular.woff2") format("woff2");
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: "Entire Mono";
  src: url("../fonts/entire-mono-bold.woff2") format("woff2");
  font-weight: 700;
  font-display: swap;
}

:root {
  color-scheme: dark;
  /* entire.io dark neutrals */
  --n0: #070707; --n50: #111; --n100: #161616; --n150: #1c1c1c;
  --n200: #222;  --n250: #292929; --n300: #333; --n400: #4e4e4e;
  --n500: #707070; --n600: #949494; --n700: #b9b9b9; --n800: #d9d9d9;
  --n900: #f3f3f3; --n1000: #fff;

  --accent: #f25533;
  --accent-soft: rgba(242, 85, 51, 0.14);

  --surface-sunken: var(--n50);
  --surface-base: var(--n100);
  --surface-raised: var(--n150);
  --surface-floating: var(--n200);

  --border: rgba(255, 255, 255, 0.1);
  --border-subtle: rgba(255, 255, 255, 0.08);

  --text: var(--n900);
  --text-muted: var(--n700);
  --text-dim: var(--n500);

  /* status colors (entire.io trail/runner palette) */
  --lime: #9ae600;
  --amber: #fdc700;
  --amber-deep: #fd9a00;
  --blue: #51a2ff;
  --indigo: #7c86ff;
  --red: #fb6461;

  --font-headline: "Entire Headline", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "Entire Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;

  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  height: 100%;
  overflow: hidden;
  background: var(--n0);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: clamp(14px, 1.05vw, 19px);
  -webkit-font-smoothing: antialiased;
}

/* ============================================================
   Stage background: dot grid + drifting accent glow
   ============================================================ */
.stage-bg {
  position: fixed; inset: 0; z-index: 0; pointer-events: none;
  background-image: radial-gradient(rgba(255,255,255,0.055) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: radial-gradient(ellipse 90% 80% at 50% 45%, black 30%, transparent 100%);
  -webkit-mask-image: radial-gradient(ellipse 90% 80% at 50% 45%, black 30%, transparent 100%);
}
.stage-glow {
  position: fixed; z-index: 0; pointer-events: none;
  width: 65vw; height: 65vw; border-radius: 50%;
  left: 50%; top: 60%;
  background: radial-gradient(circle, rgba(242,85,51,0.09) 0%, rgba(242,85,51,0.03) 40%, transparent 70%);
  transform: translate(-50%, -50%);
  animation: glow-drift 26s ease-in-out infinite alternate;
  filter: blur(20px);
}
@keyframes glow-drift {
  0%   { transform: translate(-62%, -46%) scale(1); }
  50%  { transform: translate(-42%, -58%) scale(1.15); }
  100% { transform: translate(-55%, -42%) scale(0.95); }
}

/* ============================================================
   Deck chrome
   ============================================================ */
.deck { position: fixed; inset: 0; z-index: 1; }

.progress {
  position: fixed; left: 0; bottom: 0; height: 3px; z-index: 40;
  background: var(--accent);
  width: 0;
  transition: width 0.45s var(--ease-out);
  box-shadow: 0 0 12px rgba(242, 85, 51, 0.6);
}
.hud {
  position: fixed; z-index: 40; bottom: 1.4rem;
  font-family: var(--font-mono);
  font-size: 0.72rem; letter-spacing: 0.08em;
  color: var(--text-dim);
  user-select: none;
}
.hud-counter { right: 1.8rem; }
.hud-act { left: 1.8rem; text-transform: uppercase; }
.hud-act em { color: var(--accent); font-style: normal; }
.hud-mark {
  position: fixed; z-index: 40; top: 1.5rem; right: 1.8rem;
  width: 26px; height: 26px; opacity: 0.5;
}
.hud-mark img { width: 100%; height: 100%; display: block; }

/* ============================================================
   Slides
   ============================================================ */
.slide {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  padding: 4.5rem 5.5rem 5rem;
  opacity: 0; visibility: hidden;
  transform: translateY(14px) scale(0.995);
  transition: opacity 0.5s var(--ease-out), transform 0.5s var(--ease-out), visibility 0s linear 0.5s;
  overflow: hidden;
}
.slide.active {
  opacity: 1; visibility: visible;
  transform: none;
  transition: opacity 0.55s var(--ease-out), transform 0.55s var(--ease-out);
  z-index: 10;
}
.wrap { width: min(1180px, 100%); }
.wrap-narrow { width: min(940px, 100%); }

/* entrance animation for slide children */
[data-animate] { opacity: 0; }
.slide.active [data-animate] {
  animation: rise 0.8s var(--ease-out) both;
  animation-delay: calc(var(--i, 0) * 100ms + 180ms);
}
@keyframes rise {
  from { opacity: 0; transform: translateY(26px); }
  to   { opacity: 1; transform: none; }
}

/* fragments (revealed on keypress) */
[data-fragment] {
  opacity: 0; transform: translateY(18px);
  transition: opacity 0.6s var(--ease-out), transform 0.6s var(--ease-out);
}
[data-fragment].revealed { opacity: 1; transform: none; }

/* blackout (B key) — blank the stage while demoing elsewhere */
body.blackout::after {
  content: ""; position: fixed; inset: 0;
  background: #000; z-index: 999;
}

/* ============================================================
   Shared typography & components
   ============================================================ */
.kicker {
  font-family: var(--font-mono);
  font-size: 0.78rem; font-weight: 700;
  letter-spacing: 0.22em; text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 1.6rem;
  display: flex; align-items: center; gap: 0.9rem;
}
.kicker::before {
  content: ""; display: block; width: 2.2rem; height: 1px;
  background: var(--accent); opacity: 0.7;
}

h1, h2 {
  font-family: var(--font-headline);
  font-weight: 620;
  letter-spacing: -0.015em;
  line-height: 1.04;
  text-wrap: balance;
}
h2 { font-size: clamp(2rem, 3.6vw, 3.3rem); margin-bottom: 1.2rem; }
.sub {
  color: var(--text-muted);
  font-size: clamp(1rem, 1.35vw, 1.3rem);
  line-height: 1.55;
  max-width: 62ch;
  text-wrap: pretty;
}
.sub strong, .sub em { color: var(--text); font-style: normal; }
.accent { color: var(--accent); }
.dim { color: var(--text-dim); }

.card {
  background: var(--surface-raised);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.3rem 1.5rem;
}
.card-floating {
  background: var(--surface-floating);
  box-shadow: 0 12px 40px rgba(0,0,0,0.45), 0 2px 8px rgba(0,0,0,0.3);
}
.chip {
  display: inline-flex; align-items: center; gap: 0.5em;
  font-family: var(--font-mono); font-size: 0.78rem;
  padding: 0.42em 0.85em;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface-base);
  color: var(--text-muted);
  white-space: nowrap;
}
.chip .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); flex: none; }

.mono { font-family: var(--font-mono); }

.quote-mark { color: var(--accent); font-family: var(--font-headline); }

/* ============================================================
   Slide 1 — Title
   ============================================================ */
.s-title { text-align: center; flex-direction: column; }
.s-title .logo { width: min(480px, 55vw); margin: 0 auto 2.6rem; display: block; }
.s-title h1 { font-size: clamp(1.6rem, 2.6vw, 2.4rem); color: var(--text-muted); font-weight: 480; }
.s-title h1 strong { color: var(--text); font-weight: 640; }
.s-title .title-tagline {
  margin-top: 3.2rem;
  font-family: var(--font-mono); font-size: 0.82rem;
  letter-spacing: 0.18em; text-transform: uppercase; color: var(--text-dim);
}
.s-title .title-tagline em { color: var(--accent); font-style: normal; }
.title-rule {
  width: 64px; height: 2px; background: var(--accent);
  margin: 2.4rem auto 0; border-radius: 2px;
  box-shadow: 0 0 16px rgba(242,85,51,0.7);
}

/* ============================================================
   Act dividers
   ============================================================ */
.s-act { }
.s-act .act-num {
  font-family: var(--font-headline);
  font-size: clamp(7rem, 17vw, 15rem);
  font-weight: 700; line-height: 0.9;
  color: transparent;
  -webkit-text-stroke: 1.5px rgba(255,255,255,0.16);
  user-select: none;
  position: relative;
}
.s-act .act-num::after {
  content: attr(data-n);
  position: absolute; inset: 0;
  color: var(--accent);
  -webkit-text-stroke: 0;
  clip-path: inset(62% 0 0 0);
}
.s-act h2 { font-size: clamp(2.6rem, 5vw, 4.6rem); margin-top: 1.6rem; }
.s-act .sub { margin-top: 0.8rem; }

/* ============================================================
   Slide 3 — Terminal (agent forgot everything)
   ============================================================ */
.s-forgot .cols { display: grid; grid-template-columns: 1.05fr 0.95fr; gap: 3.4rem; align-items: center; }

.term {
  background: var(--n50);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  font-family: var(--font-mono); font-size: 0.8rem; line-height: 1.75;
  box-shadow: 0 24px 60px rgba(0,0,0,0.5);
}
.term-bar {
  display: flex; align-items: center; gap: 0.45rem;
  padding: 0.6rem 0.9rem;
  background: var(--surface-raised);
  border-bottom: 1px solid var(--border-subtle);
}
.term-bar .tb { width: 10px; height: 10px; border-radius: 50%; background: var(--n300); }
.term-bar .tb-title {
  margin-left: 0.6rem; font-size: 0.68rem; color: var(--text-dim); letter-spacing: 0.06em;
}
.term-body { padding: 1rem 1.2rem 1.2rem; min-height: 15.5rem; }
.term-body .ln { white-space: pre-wrap; opacity: 0; }
.slide.active .term-body .ln {
  animation: term-ln 0.35s ease-out both;
  animation-delay: calc(var(--t) * 1ms);
}
@keyframes term-ln { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
.ln .p { color: var(--accent); }
.ln .ok { color: var(--lime); }
.ln .warn { color: var(--amber); }
.ln .tool { color: var(--blue); }
.ln .mut { color: var(--text-dim); }

/* session 1 fades to ghost as session 2 appears */
.slide.active .term-session1 { animation: term-ghost 1.2s var(--ease-out) both; animation-delay: 6.4s; }
@keyframes term-ghost { to { opacity: 0.28; filter: blur(1px) grayscale(0.5); transform: scale(0.975) translateY(-6px); } }
.term-session2 { margin-top: -8.2rem; position: relative; opacity: 0; transform: translateY(24px); }
.slide.active .term-session2 { animation: term-new 0.9s var(--ease-out) both; animation-delay: 6.9s; }
@keyframes term-new { to { opacity: 1; transform: none; } }
.term-session2 .term-body { min-height: 7rem; }
.cursor {
  display: inline-block; width: 0.55em; height: 1.1em;
  background: var(--text); vertical-align: text-bottom;
  animation: blink 1.05s steps(1) infinite;
}
@keyframes blink { 50% { opacity: 0; } }

.s-forgot h2 { font-size: clamp(2rem, 3.3vw, 3rem); }
.forgot-punch {
  margin-top: 1.8rem; padding-left: 1.2rem;
  border-left: 3px solid var(--accent);
  font-size: clamp(1.05rem, 1.4vw, 1.35rem);
  color: var(--text-muted); line-height: 1.5;
}
